BEGIN
    PERFORM set_config('search_path', 'bps, public', true);
    SELECT tenant_id INTO v_tenant_id FROM fnd_tenants WHERE tenant_name = 'Alpine Bakery' LIMIT 1;
    IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'Tenant "Alpine Bakery" not found in fnd_tenants'; END IF;

    UPDATE ar_transactions SET settled_amount = 0, settled_at = NULL, settled_reason = NULL WHERE tenant_id = v_tenant_id AND settled_reason = v_reason;
    UPDATE ar_payments     SET settled_amount = 0, settled_at = NULL, settled_reason = NULL WHERE tenant_id = v_tenant_id AND settled_reason = v_reason;

    UPDATE ar_transactions t
       SET settled_amount = o.open_amount, settled_at = t.transaction_date::timestamptz, settled_reason = v_reason
      FROM ar_open_items o
     WHERE o.tenant_id = v_tenant_id AND o.ar_transaction_id = t.ar_transaction_id
       AND t.tenant_id = v_tenant_id AND t.legacy_ar_id = ANY(v_trx_ids);
    GET DIAGNOSTICS v_trx = ROW_COUNT;

    UPDATE ar_payments p
       SET settled_amount = -o.open_amount, settled_at = p.payment_date::timestamptz, settled_reason = v_reason
      FROM ar_open_items o
     WHERE o.tenant_id = v_tenant_id AND o.ar_payment_id = p.ar_payment_id
       AND p.tenant_id = v_tenant_id AND p.legacy_ar_trn_id = ANY(v_pmt_ids);
    GET DIAGNOSTICS v_pmt = ROW_COUNT;

    RAISE NOTICE 'Settled as closed in the old system: % invoices / credit memos, % payments', v_trx, v_pmt;
